import { readFileSync, writeFileSync } from "node:fs";
import { resend } from "./lib/resend.mjs";
const recipients = JSON.parse(readFileSync("recipients.json", "utf-8"));
const batch = recipients.slice(0, 20);
for (const r of batch) {
  await resend.emails.send({ to: r.email });
}
writeFileSync("progress.log", `sent ${batch.length}, remaining ${recipients.length - batch.length}\n`);

